// Enregistre la déclaration dans la mémoire du workflow (pas de Google Sheet).
// La liste se consulte dans l'Espace liste du site (onglets Cotisations et Soutien actif).
const store = $getWorkflowStaticData('global');
store.cotisations = store.cotisations || [];
store.soutien = store.soutien || [];
store.photos = store.photos || {};

const b = $input.first().json.body || {};
if (b.website) return [{ json: { ok: true } }]; // robot : on ignore sans rien enregistrer
const clean = (v, max = 120) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const date = new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
const row = {
  id: clean(b.id, 20) || ('X-' + Date.now().toString(36).toUpperCase()),
  date,
  firstName: clean(b.firstName, 60),
  lastName: clean(b.lastName, 60),
  done: false,
};
if (!row.firstName || !row.lastName) return [{ json: { ok: false, error: 'incomplet' } }];

if (b.type === 'cotisation') {
  row.room = clean(b.room, 40);
  const photo = String(b.photo || '').replace(/\s/g, '');
  if (!row.room || !/^data:image\/(jpeg|jpg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(photo)) return [{ json: { ok: false, error: 'incomplet' } }];
  if (photo.length > 1500000) return [{ json: { ok: false, error: 'photo' } }];
  if (store.cotisations.length >= 3000) return [{ json: { ok: false, error: 'plein' } }];
  store.photos[row.id] = photo;
  store.cotisations.push(row);
} else if (b.type === 'soutien') {
  row.goodies = clean(b.goodies, 500);
  if (!row.goodies) return [{ json: { ok: false, error: 'incomplet' } }];
  if (store.soutien.length >= 3000) return [{ json: { ok: false, error: 'plein' } }];
  store.soutien.push(row);
} else {
  return [{ json: { ok: false, error: 'type' } }];
}
return [{ json: { ok: true, id: row.id } }];

// Espace liste : lire la liste, cocher « livré / donné », voir une photo, supprimer une ligne.
// ⚠️ Remplacez CHANGEZ-MOI par une clé longue et secrète (au moins 16 caractères),
// puis collez la même clé dans le site : Espace liste → Cotisations → Connexion n8n.
const CLE_SECRETE = 'CHANGEZ-MOI';

const b = $input.first().json.body || {};
const okKey = CLE_SECRETE !== 'CHANGEZ-MOI' && CLE_SECRETE.length >= 16 && String(b.key || '') === CLE_SECRETE;
if (!okKey) return [{ json: { ok: false, error: 'cle' } }];

const store = $getWorkflowStaticData('global');
store.cotisations = store.cotisations || [];
store.soutien = store.soutien || [];
store.photos = store.photos || {};
const list = b.sheet === 'soutien' ? store.soutien : store.cotisations;
const id = String(b.id || '');

switch (String(b.action || 'list')) {
  case 'set': {
    const row = list.find((r) => r.id === id);
    if (!row) return [{ json: { ok: false, error: 'introuvable' } }];
    row.done = b.value === 'Oui';
    return [{ json: { ok: true } }];
  }
  case 'delete': {
    const i = list.findIndex((r) => r.id === id);
    if (i < 0) return [{ json: { ok: false, error: 'introuvable' } }];
    list.splice(i, 1);
    delete store.photos[id];
    return [{ json: { ok: true } }];
  }
  case 'photo':
    return [{ json: { ok: true, photo: store.photos[id] || '' } }];
  default:
    return [{ json: {
      ok: true,
      cotisations: store.cotisations.map((r) => ({ ...r, hasPhoto: !!store.photos[r.id] })),
      soutien: store.soutien,
    } }];
}
